import sys
from functools import wraps


def choose_selector_way(func):
    def choose_way_select_element(self, selector, by="css"):
        select_element_script = None
        if by == "css":
            select_element_script = "document.querySelector(\"{}\")".format(selector)
        elif by == 'id':
            select_element_script = "document.getElementById(\"{}\")".format(selector)
        return func(self, select_element_script, by)

    return choose_way_select_element


def retry_after_init_failed(retry_times, exception):
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            exc_value = None
            for _ in range(retry_times):
                try:
                    return func(self, *args, **kwargs)
                except exception:
                    _, exc_value, _ = sys.exc_info()
                    if "connection refused" not in exc_value.__str__():
                        break

            raise exc_value

        return wrapper

    return decorator
